immersive-storms/general.json5:
{
	// Toggle for all fog density and color changing features
	enableFogChanges: true,
	// Toggles the fog density and color changes for sandstorms
	enableSandstormFog: true,
	// Toggles the fog density and color changes for blizzards
	enableBlizzardFog: true,
	// Toggles the fog density and color changes for dense fog (affects Pale Gardens and Swamps)
	enableDenseFog: true,
	// Enables ambient wind particles in windy biomes
	enableAmbientWindParticles: true,
	// Enables ambient wind sounds in windy biomes, has no effect in deserts/badlands due to vanilla mechanic
	enableAmbientWindSounds: true,
	// Enables the strong wind sounds from sandstorms and blizzards
	enableStrongWindSounds: true,
	// Enables the black rain effect in biomes like the Pale Garden
	enableBlackRain: true,
	// Adjusts how close fog closes in during weather, must be positive
	fogDistanceMultiplier: 1.0,
	// Adjusts how often ambient wind particles appear (does not affect sandstorms), must be positive
	windParticleChanceMultiplier: 1.0
}

immersiveui-common.json5:
{
  // DO NOT CHANGE
  schemaVersion: 0,
  inventory: {
    // Enables the hotbar selector animation.
    enableHotbarSelectorAnimation: true,
    // Enables floating item rotation.
    enableFloatingItemRotation: true,
    // Enables hovering of matching items.
    enableMatchingItemHovering: true,
    // Disables vanilla slot highlighting
    disableVanillaSlotHighlighting: true,
    // Enables particles for rare items.
    enableRarityParticles: true,
    // Affects the speed of the hotbar selector.
    hotbarSelectorSpeed: 3.0,
    // Affects the size of the hovered item.
    hoveredItemScale: 1.4,
    // Affects the size of the floating item.
    floatingItemScale: 1.4,
    // Affects the hover amplitude of items, that match to the item that is carried in the cursor.
    matchingItemHoverAmplitude: 0.8,
    // Affects the easing speed, that is applied to the rotation of the floating item.
    floatingItemEasingSpeed: 0.75,
    // Affects the rotation amplitude of the floating item.
    floatingItemRotationAmplitude: 1.0,
    // Moves the hotbar selector above the items. You might want to disable this, if you use resource packs that change the default selector texture.
    renderHotbarSelectorAboveItems: false
  },
  screenShake: {
    // Enables screen shake.
    enableScreenShake: true,
    // Screen shake timer in ticks.
    shakeTimer: 8,
    // Screen shake amplitude.
    shakeAmplitude: 1.25
  },
  enchantments: {
    // Enables particles in the enchant(ing/ment) table.
    enableEnchantParticles: true,
    // Enables special formatting for items with cursed enchantments.
    enableCurseFormatting: true
  },
  misc: {
    // Enables wobbly items in advancement toasts.
    enableAdvancementToastItems: true
  }
}

